/**
 * Shape of json/upgrade-costs.json, generated by tools-js/build-upgrade-costs.cjs
 * from the game's master data.
 */
declare interface UpgradeMaterial {
  mst_material_id: number;
  amount: number;
}

declare interface UpgradePiece {
  /** Master name, in Japanese, as stored by the game. */
  name: string;
  rarity: number;
  levelMax: number;
  /** Row into strengthRef. */
  strengthenNeedMaterialId: number;
}

declare interface UpgradeCosts {
  _comment: string;
  _formula: string;
  /** rarity -> flat per-level zeny base. */
  zenyByRarity: Record<string, number>;
  /** Material-set index -> its (up to four) materials. */
  materialSets: Record<string, UpgradeMaterial[]>;
  /**
   * strengthenNeedMaterialId -> the set index for each level step:
   * `strengthRef[id][lv]` is the set used to go from level `lv` to `lv + 1`
   * (-1 / absent means no step from that level).
   */
  strengthRef: Record<string, number[]>;
  /** mst_equipment_id -> cost data. */
  equipment: Record<string, UpgradePiece>;
}

declare const COSTI: UpgradeCosts;
export default COSTI;
